      <p>The first match at <strong>Wagener Stadium</strong> after the opening ceremony is <strong>Argentina vs Chile (Pool A) at 15:00 CEST (18:30 IST / 18:00 PKT)</strong>. The first match at <strong>Belfius Hockey Arena, Wavre</strong> (simultaneous with the opening ceremony) is <strong>Australia vs South Africa (Pool C) at 13:00 CEST</strong>. The <strong>most anticipated opening-day match — England vs Pakistan</strong> — follows at <strong>17:30 CEST at Wagener Stadium</strong>. See the full <a href="/schedule">Tournament Schedule</a> and <a href="/hockey-world-cup-2026-schedule-netherlands">Netherlands schedule hub</a>.</p>
