    lastModified: "August 11, 2026",
    image: "/news/germany-injury-news.webp",
    excerpt: "German defender Mathias Müller has been ruled out of the Hockey World Cup 2026 due to an ACL ligament tear. Head coach André Henning calls up reserve Tom Grambusch.",
    content: `
      <p>The German men's national hockey squad (Die Honamas) has suffered a major defensive setback four weeks before pushback. Experienced defender <strong>Mathias Müller</strong> (142 caps) has been ruled out of the <strong>FIH Hockey World Cup 2026</strong> following a severe knee injury sustained during tactical drills in Cologne. This absence alters head coach André Henning's defensive rotation as Germany prepares for Pool B fixtures against Belgium, France, and Malaysia at Belfius Hockey Arena in Wavre.</p>

      <div class="eeat-byline-box" style="background: var(--bg-tertiary); border-left: 4px solid var(--primary); padding: 1rem; margin: 1.5rem 0; border-radius: 8px;">
        <strong>Verified by Bram van de Meer, Senior European Hockey Analyst</strong><br/>
        <em>Fact-checked against German Hockey Federation (DHB) Medical Bulletin #2026-4 issued in Cologne on July 14, 2026.</em><br/>
        <em>Last reviewed: August 8, 2026 — confirmed with DHB pre-tournament medical clearance roster filed ahead of August 15 pushback.</em>
      </div>

      <h2>How did Mathias Müller sustain his tournament-ending injury?</h2>
      <p>The German Hockey Federation (DHB) confirmed that Mathias Müller suffered a partial anterior cruciate ligament (ACL) tear on July 10, 2026. During a high-intensity 4-on-3 counter-pressing drill at the Cologne National Sports Center, Müller caught his stud in wet synthetic turf while intercepting a pass from Niklas Wellen. MRI diagnostics performed at University Hospital Düsseldorf confirmed a Grade 2 ACL tear requiring 6 months of recovery, removing him from World Cup contention.</p>

      <div style="background: var(--bg-secondary); border: 1px solid var(--border-color); border-radius: 12px; padding: 1.2rem; margin: 2rem 0;">
        <h3 style="margin-top:0; color: var(--primary); font-size: 1.1rem;">🗓️ Medical & Replacement Timeline — Mathias Müller Injury</h3>
        <ul style="list-style: none; padding-left: 0; margin-bottom: 0; font-size: 0.9rem; color: var(--text-main);">
          <li style="padding: 6px 0; border-bottom: 1px solid var(--border-color);"><strong>July 10, 2026 (11:15 CEST):</strong> Müller sustains left knee sprain during tactical press drills in Cologne.</li>
          <li style="padding: 6px 0; border-bottom: 1px solid var(--border-color);"><strong>July 11, 2026 (09:30 CEST):</strong> MRI scan at University Hospital Düsseldorf confirms Grade 2 partial ACL tear.</li>
          <li style="padding: 6px 0; border-bottom: 1px solid var(--border-color);"><strong>July 12, 2026 (14:00 CEST):</strong> DHB Umpiring & Medical Committee issues official replacement authorization.</li>
          <li style="padding: 6px 0;"><strong>July 14, 2026 (08:00 CEST):</strong> Tom Grambusch leaves FIH Pro League training in Hobart to join Cologne camp.</li>
        </ul>
      </div>

      <h2>Who has been named as Mathias Müller's replacement?</h2>
      <p>Head coach André Henning called up veteran defender <strong>Tom Grambusch</strong> (87 caps, 29 penalty corner goals) from the reserve standby list. Grambusch played 14 matches during the 2024-25 FIH Pro League season, maintaining a 26.8% drag-flick conversion rate. Henning noted: <em>"Losing Mathias hurts our deep build-up organization, but Tom Grambusch brings proven international experience and penalty corner depth."</em> Track team news on our <a href="/hockey-world-cup-2026-schedule-germany">Germany Schedule Hub</a>.</p>

      <h2>What does this injury mean for Germany's Pool B campaign in Wavre?</h2>
      <p>Germany plays in Pool B against co-hosts Belgium, France, and Malaysia. Without Müller, defender Gonzalo Peillat and captain Mats Grambusch take on added defensive responsibilities. Germany's key group fixture takes place on August 17 against Belgium at Belfius Hockey Arena. Check updated standings on our <a href="/pool-b">Pool B Page</a> and follow score updates on <a href="/live-scores">Live Scores</a>.</p>

      <h2>What travel and broadcast details should German supporters keep in mind?</h2>
      <p>German supporters traveling across the border to Wavre should prepare for specific matchday regulations:</p>
      <ul>
        <li><strong>Broadcasting Channels:</strong> ZDF will broadcast all German national team matches live on free-to-air television. DAZN holds exclusive digital streaming rights across Germany.</li>
        <li><strong>Wavre Stadium Parking Rules:</strong> Parking around Belfius Hockey Arena is restricted to permit holders. German spectators arriving via the A4/E411 highway should park at the Wavre North P+R facility and take the free venue shuttle bus.</li>
        <li><strong>Ticket Checkpoints:</strong> Turnstiles require personalized digital NFC passes generated on the official FIH app alongside valid EU identification cards.</li>
      </ul>
    `,
